	rec := httptest.NewRecorder()

	handlers.Register(repository.NewMemStore())(rec, httptest.NewRequest(http.MethodPost, "/devices", strings.NewReader("{")))

	if rec.Code != http.StatusBadRequest {
		t.Fatalf("status %d, want 400", rec.Code)
